import { EventEmitter } from 'eventemitter3';

export interface WorkspaceEventMap {
  'workspace:opened': { projectId: string };
  'workspace:closed': { projectId: string };
  'workspace:switched': { fromProjectId: string; toProjectId: string };
}

export const workspaceEvents = new EventEmitter<WorkspaceEventMap>();

import { create } from 'zustand';

// Navigation state types
export interface NavigationState {
  currentFile: string | null;
  currentDirectory: string | null;
  openFiles: string[];
  expandedFolders: string[];
  selectedPanel: 'editor' | 'terminal' | 'preview';
  sidebarTab: 'files' | 'search' | 'git' | 'extensions';
}

// Store implementation
export const useNavigationStore = create<NavigationState>((set) => ({
  currentFile: null,
  currentDirectory: null,
  openFiles: [],
  expandedFolders: [],
  selectedPanel: 'editor',
  sidebarTab: 'files',
}));
